import type { Graph, NodeFact, EdgeFact } from '../src/types.ts';

/**
 * The whole spike's test input: one small Java program, written out by hand as a Graph.
 *
 * Hand-written on purpose. A fixture generated by Joern would make every unit test a test of Joern,
 * would cost two and a half minutes to regenerate, and would quietly absorb whatever Joern did
 * wrong. This one instead states what `spike/joern/export.sc` is *required* to produce, and
 * `spike/test/extract.sh` is the one thing that checks reality against it.
 *
 * The program it stands for:
 *
 *   Api.java                                  Svc.java
 *   16  @Path("/loans") class Api             8   class Svc {
 *   20    @POST @Path("{id}/charge")          9     BigDecimal total;
 *   20    Response addCharge(id, amount) {    10    BigDecimal apply(loan, amount) {
 *   22      Loan loan = repo.findById(id);    11      this.total = amount;
 *   23      BigDecimal t = svc.apply(...);    12      BigDecimal t = this.total;
 *   24      repo.save(loan);                  13      loan.setAmount(t);
 *   25      return Response.ok(t);            14      return t;
 *                                             30    Rule pick(rules) {
 *                                             31      return rules.stream().findFirst().get();
 *                                             40    void spin() {
 *                                             41      a = b + 1;
 *                                             42      b = a + 1;
 *
 * Every interesting shape in Fineract is in there once: a JAX-RS endpoint, a repository read and a
 * repository write, a value crossing a call and coming back through a return, a value crossing a
 * *field* with no call between writer and reader, an exception thrown by the JDK with no `throw` in
 * the source, and a two-statement cycle.
 */

const API = 'app.api.Api';
const SVC = 'app.svc.Svc';
const API_FILE = 'app/api/Api.java';
const SVC_FILE = 'app/svc/Svc.java';

const ADD_CHARGE = 'app.api.Api.addCharge:jakarta.ws.rs.core.Response(java.lang.Long,java.math.BigDecimal)';
const APPLY = 'app.svc.Svc.apply:java.math.BigDecimal(app.domain.Loan,java.math.BigDecimal)';
const PICK = 'app.svc.Svc.pick:app.domain.Rule(java.util.List)';
const SPIN = 'app.svc.Svc.spin:void()';

function n(id: string, label: string, code: string, file: string, line: number, method: string, rest: Partial<NodeFact> = {}): NodeFact {
  return { id, label, code, file, line, method, ...rest };
}

const rd = (from: string, to: string): EdgeFact => ({ kind: 'rd', from, to });

export function hand(): Graph {
  const nodes: NodeFact[] = [
    // --- Api.addCharge -------------------------------------------------------------------------
    n('a-id', 'METHOD_PARAMETER_IN', 'Long id', API_FILE, 20, ADD_CHARGE),
    n('a-amt', 'METHOD_PARAMETER_IN', 'BigDecimal amount', API_FILE, 20, ADD_CHARGE),

    n('a22-assign', 'CALL', 'Loan loan = repo.findById(id)', API_FILE, 22, ADD_CHARGE, {
      name: '<operator>.assignment', methodFullName: '<operator>.assignment', args: ['a22-loan', 'a22-find'],
    }),
    n('a22-loan', 'IDENTIFIER', 'loan', API_FILE, 22, ADD_CHARGE),
    n('a22-find', 'CALL', 'repo.findById(id)', API_FILE, 22, ADD_CHARGE, {
      name: 'findById',
      methodFullName: 'app.repo.LoanRepository.findById:app.domain.Loan(java.lang.Long)',
      receiverType: 'app.repo.LoanRepository',
      args: ['a22-repo', 'a22-idarg'],
    }),
    n('a22-repo', 'CALL', 'this.repo', API_FILE, 22, ADD_CHARGE, {
      name: '<operator>.fieldAccess', methodFullName: '<operator>.fieldAccess', member: 'Api.repo',
    }),
    n('a22-idarg', 'IDENTIFIER', 'id', API_FILE, 22, ADD_CHARGE),

    n('a23-assign', 'CALL', 'BigDecimal t = svc.apply(loan, amount)', API_FILE, 23, ADD_CHARGE, {
      name: '<operator>.assignment', methodFullName: '<operator>.assignment', args: ['a23-t', 'a23-apply'],
    }),
    n('a23-t', 'IDENTIFIER', 't', API_FILE, 23, ADD_CHARGE),
    n('a23-apply', 'CALL', 'svc.apply(loan, amount)', API_FILE, 23, ADD_CHARGE, {
      name: 'apply', methodFullName: APPLY, receiverType: SVC, args: ['a23-svc', 'a23-loan', 'a23-amt'],
    }),
    n('a23-svc', 'CALL', 'this.svc', API_FILE, 23, ADD_CHARGE, {
      name: '<operator>.fieldAccess', methodFullName: '<operator>.fieldAccess', member: 'Api.svc',
    }),
    n('a23-loan', 'IDENTIFIER', 'loan', API_FILE, 23, ADD_CHARGE),
    n('a23-amt', 'IDENTIFIER', 'amount', API_FILE, 23, ADD_CHARGE),

    n('a24-save', 'CALL', 'repo.save(loan)', API_FILE, 24, ADD_CHARGE, {
      name: 'save',
      methodFullName: 'app.repo.LoanRepository.save:app.domain.Loan(app.domain.Loan)',
      receiverType: 'app.repo.LoanRepository',
      args: ['a24-repo', 'a24-loan'],
    }),
    n('a24-repo', 'CALL', 'this.repo', API_FILE, 24, ADD_CHARGE, {
      name: '<operator>.fieldAccess', methodFullName: '<operator>.fieldAccess', member: 'Api.repo',
    }),
    n('a24-loan', 'IDENTIFIER', 'loan', API_FILE, 24, ADD_CHARGE),

    n('a25-return', 'RETURN', 'return Response.ok(t)', API_FILE, 25, ADD_CHARGE),
    n('a25-ok', 'CALL', 'Response.ok(t)', API_FILE, 25, ADD_CHARGE, {
      name: 'ok', methodFullName: '<unresolvedNamespace>.Response.ok:<unresolvedSignature>(1)',
      receiverType: '<unresolvedNamespace>.Response', args: ['a25-t'],
    }),
    n('a25-t', 'IDENTIFIER', 't', API_FILE, 25, ADD_CHARGE),

    // --- Svc.apply -----------------------------------------------------------------------------
    n('s-loan', 'METHOD_PARAMETER_IN', 'Loan loan', SVC_FILE, 10, APPLY),
    n('s-amt', 'METHOD_PARAMETER_IN', 'BigDecimal amount', SVC_FILE, 10, APPLY),

    n('s11-assign', 'CALL', 'this.total = amount', SVC_FILE, 11, APPLY, {
      name: '<operator>.assignment', methodFullName: '<operator>.assignment', args: ['s11-total', 's11-amt'],
    }),
    n('s11-total', 'CALL', 'this.total', SVC_FILE, 11, APPLY, {
      name: '<operator>.fieldAccess', methodFullName: '<operator>.fieldAccess', member: 'Svc.total',
    }),
    n('s11-amt', 'IDENTIFIER', 'amount', SVC_FILE, 11, APPLY),

    n('s12-assign', 'CALL', 'BigDecimal t = this.total', SVC_FILE, 12, APPLY, {
      name: '<operator>.assignment', methodFullName: '<operator>.assignment', args: ['s12-t', 's12-total'],
    }),
    n('s12-t', 'IDENTIFIER', 't', SVC_FILE, 12, APPLY),
    n('s12-total', 'CALL', 'this.total', SVC_FILE, 12, APPLY, {
      name: '<operator>.fieldAccess', methodFullName: '<operator>.fieldAccess', member: 'Svc.total',
    }),

    n('s13-set', 'CALL', 'loan.setAmount(t)', SVC_FILE, 13, APPLY, {
      name: 'setAmount',
      methodFullName: '<unresolvedNamespace>.Loan.setAmount:<unresolvedSignature>(1)',
      receiverType: '<unresolvedNamespace>.Loan',
      args: ['s13-loan', 's13-t'],
    }),
    n('s13-loan', 'IDENTIFIER', 'loan', SVC_FILE, 13, APPLY),
    n('s13-t', 'IDENTIFIER', 't', SVC_FILE, 13, APPLY),

    n('s14-return', 'RETURN', 'return t', SVC_FILE, 14, APPLY),
    n('s14-t', 'IDENTIFIER', 't', SVC_FILE, 14, APPLY),

    // --- Svc.pick: an exception the JDK throws, with no `throw` in the source --------------------
    n('p31-return', 'RETURN', 'return rules.stream().findFirst().get()', SVC_FILE, 31, PICK),
    n('p31-get', 'CALL', 'rules.stream().findFirst().get()', SVC_FILE, 31, PICK, {
      name: 'get',
      methodFullName: '<unresolvedNamespace>.Optional.get:<unresolvedSignature>(0)',
      receiverType: '<unresolvedNamespace>.Optional',
      args: ['p31-findFirst'],
    }),
    n('p31-findFirst', 'CALL', 'rules.stream().findFirst()', SVC_FILE, 31, PICK, {
      name: 'findFirst', methodFullName: '<unresolvedNamespace>.Stream.findFirst:<unresolvedSignature>(0)',
      receiverType: '<unresolvedNamespace>.Stream', args: ['p31-stream'],
    }),
    n('p31-stream', 'CALL', 'rules.stream()', SVC_FILE, 31, PICK, {
      name: 'stream', methodFullName: '<unresolvedNamespace>.List.stream:<unresolvedSignature>(0)',
      receiverType: '<unresolvedNamespace>.List', args: ['p31-rules'],
    }),
    n('p31-rules', 'IDENTIFIER', 'rules', SVC_FILE, 31, PICK),

    // --- Svc.spin: the cycle ---------------------------------------------------------------------
    n('x41-assign', 'CALL', 'a = b + 1', SVC_FILE, 41, SPIN, {
      name: '<operator>.assignment', methodFullName: '<operator>.assignment', args: ['x41-a', 'x41-add'],
    }),
    n('x41-a', 'IDENTIFIER', 'a', SVC_FILE, 41, SPIN),
    n('x41-add', 'CALL', 'b + 1', SVC_FILE, 41, SPIN, {
      name: '<operator>.addition', methodFullName: '<operator>.addition', args: ['x41-b', 'x41-one'],
    }),
    n('x41-b', 'IDENTIFIER', 'b', SVC_FILE, 41, SPIN),
    n('x41-one', 'LITERAL', '1', SVC_FILE, 41, SPIN),

    n('x42-assign', 'CALL', 'b = a + 1', SVC_FILE, 42, SPIN, {
      name: '<operator>.assignment', methodFullName: '<operator>.assignment', args: ['x42-b', 'x42-add'],
    }),
    n('x42-b', 'IDENTIFIER', 'b', SVC_FILE, 42, SPIN),
    n('x42-add', 'CALL', 'a + 1', SVC_FILE, 42, SPIN, {
      name: '<operator>.addition', methodFullName: '<operator>.addition', args: ['x42-a', 'x42-one'],
    }),
    n('x42-a', 'IDENTIFIER', 'a', SVC_FILE, 42, SPIN),
    n('x42-one', 'LITERAL', '1', SVC_FILE, 42, SPIN),
  ];

  const edges: EdgeFact[] = [
    // Api.addCharge: id -> findById -> loan -> apply/save; amount -> apply; t -> return.
    rd('a-id', 'a22-idarg'),
    rd('a22-loan', 'a23-loan'),
    rd('a22-loan', 'a24-loan'),
    rd('a-amt', 'a23-amt'),
    rd('a23-t', 'a25-t'),
    // Svc.apply: amount -> the field write; the field read -> t -> setAmount and the return.
    rd('s-amt', 's11-amt'),
    rd('s12-t', 's13-t'),
    rd('s12-t', 's14-t'),
    // loan reaches setAmount and stops there. It never reaches the return, which is what keeps the
    // pair set from degenerating into "every input reaches every output".
    rd('s-loan', 's13-loan'),
    // Svc.spin: a defined at 41 is read at 42, and b defined at 42 is read at 41.
    rd('x41-a', 'x42-a'),
    rd('x42-b', 'x41-b'),
  ];

  return {
    version: 1,
    commit: 'hand-written',
    types: [
      {
        fullName: API, name: 'Api', file: API_FILE,
        annotations: [{ name: 'Path', value: '"/loans"' }],
        members: [
          { name: 'repo', type: 'app.repo.LoanRepository', annotations: [{ name: 'Autowired' }] },
          { name: 'svc', type: SVC, annotations: [{ name: 'Autowired' }] },
        ],
      },
      {
        fullName: SVC, name: 'Svc', file: SVC_FILE, annotations: [{ name: 'Service' }],
        members: [{ name: 'total', type: 'java.math.BigDecimal', annotations: [] }],
      },
      {
        fullName: 'app.domain.Loan', name: 'Loan', file: 'app/domain/Loan.java',
        annotations: [{ name: 'Entity' }, { name: 'Table', value: '"m_loan"' }],
        members: [{ name: 'amount', type: 'java.math.BigDecimal', annotations: [{ name: 'Column', value: '"amount"' }] }],
      },
    ],
    methods: [
      {
        fullName: ADD_CHARGE, name: 'addCharge', typeName: 'Api', typeFullName: API,
        file: API_FILE, line: 20,
        annotations: [{ name: 'POST' }, { name: 'Path', value: '"{id}/charge"' }],
        params: [
          { id: 'a-id', name: 'id', index: 1, line: 20, type: 'java.lang.Long' },
          { id: 'a-amt', name: 'amount', index: 2, line: 20, type: 'java.math.BigDecimal' },
        ],
        returns: ['a25-return'],
      },
      {
        fullName: APPLY, name: 'apply', typeName: 'Svc', typeFullName: SVC,
        file: SVC_FILE, line: 10, annotations: [],
        params: [
          { id: 's-loan', name: 'loan', index: 1, line: 10, type: 'app.domain.Loan' },
          { id: 's-amt', name: 'amount', index: 2, line: 10, type: 'java.math.BigDecimal' },
        ],
        returns: ['s14-return'],
      },
      {
        fullName: PICK, name: 'pick', typeName: 'Svc', typeFullName: SVC,
        file: SVC_FILE, line: 30, annotations: [],
        params: [{ id: 'p-rules', name: 'rules', index: 1, line: 30, type: 'java.util.List' }],
        returns: ['p31-return'],
      },
      {
        fullName: SPIN, name: 'spin', typeName: 'Svc', typeFullName: SVC,
        file: SVC_FILE, line: 40, annotations: [], params: [], returns: [],
      },
    ],
    nodes,
    edges,
  };
}

/** Statement keys the fixture's tests name often enough to be worth spelling once. */
export const KEY = {
  endpoint: 'app/api/Api.java:20',
  findById: 'app/api/Api.java:22',
  apply: 'app/api/Api.java:23',
  save: 'app/api/Api.java:24',
  respond: 'app/api/Api.java:25',
  applyDecl: 'app/svc/Svc.java:10',
  fieldWrite: 'app/svc/Svc.java:11',
  fieldRead: 'app/svc/Svc.java:12',
  setAmount: 'app/svc/Svc.java:13',
  applyReturn: 'app/svc/Svc.java:14',
  optionalGet: 'app/svc/Svc.java:31',
  spinA: 'app/svc/Svc.java:41',
  spinB: 'app/svc/Svc.java:42',
} as const;
